// Rows of the printed polynomial tiling. Each whole cell is one polynomial of
// degree 2--6, calibrated jointly with every cell of that type on the page.
// The (1-u^2) factor enforces a shared endpoint between adjacent cells.
function eqPolynomialTilingPlan(e,st){
 const model=eqPolynomialTilingModels[e.page];if(!model)return null;
 const byOld=new Map(st.m.sourceIndexes.map((n,i)=>[n,st.m.paths[i]])),used=new Set(),curves=[];
 const number=x=>Number(x.toFixed(7)).toString();
 model.rows.forEach(([Y,cells0],rowIndex)=>{
  const cells=cells0.filter(a=>byOld.has(a[0]));if(!cells.length)return;const lookup=new Map(cells.map(a=>[a[1],a])),first=cells[0][1],last=cells.at(-1)[1],c=(model.Y-Y)/model.H;
  for(const cell of cells)used.add(byOld.get(cell[0]));
  const cellAt=t=>lookup.get(Math.max(first,Math.min(last,Math.floor(t+1e-10))));
  const value=t=>{const cell=cellAt(t);if(!cell)return null;const u=2*(t-cell[1])-1,f=model.types[cell[2]],P=(1-u*u)*f.coef.reduce((s,a,i)=>s+a*u**f.powers[i],0);return{cell,u,P,f}};
  const tex=t=>{const q=value(t);if(!q)return '';const polynomial=q.f.coef.map((a,i)=>'('+number(-a/model.H)+')'+(q.f.powers[i]?'u'+(q.f.powers[i]===1?'':'^{'+q.f.powers[i]+'}'):'')).join('+');return '\\begin{aligned}x(t)&=t\\\\u&=2(t-'+q.cell[1]+')-1\\\\y(t)&='+number(c)+'+(1-u^2)\\left('+polynomial+'\\right)\\end{aligned}'};
  curves.push({r:byOld.get(cells[0][0]),t0:first,t1:last+1,count:Math.max(240,cells.length*64),eval:t=>{const q=value(t);return q?[model.O+model.W*t,Y+q.P]:[NaN,NaN]},math:t=>{const q=value(t);return q?[t,c-q.P/model.H]:[NaN,NaN]},tex,params:t=>{const q=value(t);return '第 '+(rowIndex+1)+' / '+model.rows.length+' 行 · 第 '+(q.cell[1]+1)+' 个单元 · '+q.cell[2]+' 次多项式 · 行高 c = '+eqpN(c,5)+' · 局部参数 u = '+eqpN(q.u,5)},_tilingCells:cells,_tilingRow:Y});
 });
 return{curves,refs:st.m.paths.filter(r=>!used.has(r)),note:'按原书逐行拼接多项式；x 连续改变时，自动切换当前单元的完整多项式。书中未给出系数，这里用全图各同类单元共同标定；以单元宽、行间距为坐标单位，端点因子 (1−u²) 保证各段相接。'};
}
